import React from 'react';
import { Composition, staticFile } from 'remotion';

import { framesFor, type Manifest, SecretsApi } from './Video';

const FPS = 30;

export const RemotionRoot: React.FC = () => (
	<Composition
		id="SecretsApi"
		component={ SecretsApi }
		width={ 1920 }
		height={ 1080 }
		fps={ FPS }
		durationInFrames={ FPS * 10 }
		defaultProps={ { manifest: { source: 'scratch', scenes: [] } as Manifest } }
		calculateMetadata={ async () => {
			// Generated by `npm run narrate`; scene lengths follow the voiceover.
			const manifest: Manifest = await fetch( staticFile( 'audio/manifest.json' ) ).then( r => r.json() );
			const durationInFrames = manifest.scenes.reduce( ( sum, s ) => sum + framesFor( s.seconds, FPS ), 0 );
			return { durationInFrames, props: { manifest } };
		} }
	/>
);
